<?php

declare(strict_types=1);

use AzGuard\Diagnostics\Doctor;
use AzGuard\Diagnostics\DoctorFinding;
use AzGuard\Panels\PanelBuilder;
use AzGuard\Sources\Database\DatabaseSource;
use AzGuard\Storage\StorageRegistry;
use AzGuard\Tests\Fixtures\Diagnostics\DoctorWorld;
use AzGuard\Tests\Fixtures\Diagnostics\ProbeCheck;
use AzGuard\Tests\Fixtures\Panels\OrderPermission;
use AzGuard\Tests\Fixtures\Panels\TestPanel;
use AzGuard\Tests\Fixtures\Panels\User;

it('unreachable named connection is an error', function (): void {
    config([
        'database.connections.missing_conn' => [
            'driver' => 'pgsql',
            'host' => '127.0.0.1',
            'port' => 1,
            'database' => 'azguard_test',
            'username' => 'azguard',
            'password' => 'secret-value',
            'connect_timeout' => 1,
        ],
        'azguard.storages' => [
            'default' => [],
            'ghost' => ['connection' => 'missing_conn'],
        ],
    ]);
    app()->forgetInstance(\AzGuard\Configuration\AzGuardConfig::class);
    app()->forgetInstance(StorageRegistry::class);

    DoctorWorld::migrate();
    DoctorWorld::panels([
        TestPanel::class => static function (PanelBuilder $panel): void {
            $panel->for(User::class)->permissions([
                OrderPermission::class,
                DatabaseSource::make()->storage('ghost'),
            ]);
        },
    ]);

    $findings = DoctorWorld::run();
    $migrated = DoctorWorld::only($findings, 'storage.migrated');
    $schema = DoctorWorld::only($findings, 'storage.schema');
    echo "\nMIGRATED:\n".json_encode(array_map(fn ($f) => $f->toArray(), $migrated), JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)."\n";
    echo "SCHEMA:\n".json_encode(array_map(fn ($f) => $f->toArray(), $schema), JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES)."\n";
    echo "ALL KEYS: ".implode(', ', array_map(fn ($f) => $f->scope.' '.$f->key.' '.$f->severity->value, $findings))."\n";
    expect(true)->toBeTrue();
});

it('short and username secrets survive redaction', function (): void {
    config([
        'database.connections.secondary.password' => 'pw',
        'database.connections.secondary.username' => 'UniqueUser99',
        'database.connections.secondary.url' => 'pgsql://UniqueUser99:pw@db.example:5432/app',
        'azguard.sources.ldap' => ['bind_dn' => 'cn=UniqueUser99,dc=example', 'password' => 'pw'],
    ]);
    app()->forgetInstance(\AzGuard\Configuration\AzGuardConfig::class);
    DoctorWorld::migrate();
    DoctorWorld::panels([
        TestPanel::class => static function (PanelBuilder $panel): void {
            $panel->for(User::class)->permissions([OrderPermission::class, DatabaseSource::make()])
                ->doctorChecks([new ProbeCheck('probe.leaky', static fn (): array => [
                    DoctorFinding::warning('probe.leaky', 'user UniqueUser99 password pw url pgsql://UniqueUser99:pw@db.example:5432/app', details: [
                        'note' => 'bind cn=UniqueUser99 password pw',
                    ]),
                ])]);
        },
    ]);
    $findings = DoctorWorld::run();
    $leaky = DoctorWorld::only($findings, 'probe.leaky')[0];
    echo "\nLEAKY MESSAGE: ".$leaky->message."\n";
    echo "LEAKY DETAILS: ".json_encode($leaky->details)."\n";
    expect(true)->toBeTrue();
});

it('wrong connection name that does not exist in config', function (): void {
    config([
        'azguard.storages' => [
            'default' => [],
            'ghost' => ['connection' => 'no_such_connection'],
        ],
    ]);
    app()->forgetInstance(\AzGuard\Configuration\AzGuardConfig::class);
    app()->forgetInstance(StorageRegistry::class);
    try {
        DoctorWorld::migrate();
        DoctorWorld::panels([
            TestPanel::class => static function (PanelBuilder $panel): void {
                $panel->for(User::class)->permissions([
                    OrderPermission::class,
                    DatabaseSource::make()->storage('ghost'),
                ]);
            },
        ]);
        $findings = DoctorWorld::run();
        echo "\nWRONG CONN KEYS: ".implode(' | ', array_map(fn ($f) => $f->scope.' '.$f->key.' '.$f->severity->value.' :: '.$f->message, $findings))."\n";
    } catch (Throwable $e) {
        echo "\nWRONG CONN THREW ".get_class($e).': '.$e->getMessage()."\n";
    }
    expect(true)->toBeTrue();
});
